def sort_population_verifier_oracle(
        values: tuple[int, ...] | list[int], output_capacity: int | None = None,
        output_is_null: bool = False) -> tuple[int, bytes]:
    """Independently sort bounded population records and serialize each cost/ID pair."""
    if (not isinstance(values, (tuple, list)) or not 1 <= len(values) <= 129
            or any(type(value) is not int or not -(2**63) <= value < 2**63
                   for value in values)):
        return -1, b""
    count = values[0]
    if not 1 <= count <= 64 or len(values) != 1 + 2 * count:
        return -1, b""
    records = [(values[1 + 2 * index], values[2 + 2 * index])
               for index in range(count)]
    costs = [cost for cost, _ in records]
    identifiers = [identifier for _, identifier in records]
    if (any(not -1_000_000 <= cost <= 1_000_000 for cost in costs)
            or len(set(costs)) != count
            or sorted(identifiers) != list(range(count))):
        return -1, b""
    output = b"".join(struct.pack("<qq", cost, identifier)
                      for cost, identifier in sorted(records))
    if (type(output_is_null) is not bool
            or (output_capacity is not None
                and (type(output_capacity) is not int or output_capacity < 0))):
        return -1, b""
    if output_is_null or (output_capacity is not None
                          and len(output) > output_capacity):
        return -2, b""
    return len(output), output


def adaline_learning_verifier_oracle(values: tuple[int, ...] | list[int]) -> tuple[int, bytes]:
    """Model sequential fixed-point ADALINE learning independently of the recorder."""
    if (not isinstance(values, (tuple, list)) or not 5 <= len(values) <= 293
            or any(type(value) is not int or not -(2**63) <= value < 2**63 for value in values)):
        return -1, b""
    sample_count, feature_count, eta_numerator, eta_shift, max_iterations = values[:5]
    if (not 1 <= sample_count <= 32 or not 1 <= feature_count <= 8
            or eta_numerator <= 0 or not 1 <= eta_shift <= 12
            or not 1 <= max_iterations <= 500 or eta_numerator >= 1 << eta_shift
            or len(values) != 5 + sample_count * (feature_count + 1)):
        return -1, b""
    rows: list[tuple[tuple[int, ...], int]] = []
    for offset in range(5, len(values), feature_count + 1):
        row = values[offset:offset + feature_count + 1]
        features, label = tuple(row[:-1]), row[-1]
        if any(not -16 <= feature <= 16 for feature in features) or label not in (-1, 1):
            return -1, b""
        rows.append((features, label))
    scale = 1 << eta_shift
    weights = [scale] * feature_count
    bias = scale
    completed_epochs = 0
    for _ in range(max_iterations):
        mistakes = 0
        for features, label in rows:
            score = bias + sum(feature * weight for feature, weight in zip(features, weights))
            prediction = 1 if score > 0 else -1
            if prediction != label:
                mistakes += 1
                correction = eta_numerator * (label - prediction)
                weights = [weight + correction * feature for weight, feature in zip(weights, features)]
                bias += correction
        completed_epochs += 1
        if mistakes == 0:
            break
    predictions = [1 if bias + sum(feature * weight for feature, weight in zip(features, weights)) > 0 else -1
                   for features, _ in rows]
    outputs = [completed_epochs, *weights, bias, *predictions]
    encoded = b"".join(struct.pack("<i", value) for value in outputs)
    return len(encoded), encoded


def adams_bashforth_verifier_oracle(values: tuple[int, ...] | list[int]) -> tuple[int, bytes]:
    """Independent bounded source model of the four Adams-Bashforth recurrences."""
    if (not isinstance(values, (tuple, list)) or len(values) < 3
            or any(type(value) is not int or not -(2**63) <= value < 2**63 for value in values)):
        return -1, b""
    order, forecast_steps = values[:2]
    initial_scaled = values[2:]
    if (order not in (2, 3, 4, 5) or not 1 <= forecast_steps <= 4
            or len(initial_scaled) != order
            or any(not -100_000 <= value <= 100_000 for value in initial_scaled)):
        return -1, b""
    coefficients = {2: (3, -1), 3: (23, -16, 5),
                    4: (55, -59, 37, -9), 5: (1901, -2774, -2616, -1274, 251)}[order]
    denominator = {2: 2.0, 3: 12.0, 4: 24.0, 5: 720.0}[order]
    xs = [index * 0.25 for index in range(order)]
    ys = [value / 100_000.0 for value in initial_scaled]
    updates = forecast_steps + (order in (3, 5))
    for _ in range(updates):
        derivative_sum = 0.0
        for offset, coefficient in enumerate(coefficients):
            index = len(ys) - 1 - offset
            derivative_sum += coefficient * (xs[index] + ys[index])
        ys.append(ys[-1] + (0.25 / denominator) * derivative_sum)
        xs.append(xs[-1] + 0.25)
    encoded = ",".join(str(math.trunc(value * 1_000_000.0)) for value in ys).encode("ascii")
    return len(encoded), encoded


def adfgvxcipher_verifier_oracle(values: tuple[int, ...] | list[int]) -> tuple[int, bytes]:
    """Independent ASCII ADFGVX oracle with source-compatible partial columns."""
    if (not isinstance(values, (tuple, list)) or not 3 <= len(values) <= 531
            or any(type(value) is not int or not -(2**63) <= value < 2**63 for value in values)):
        return -1, b""
    mode, text_length, key_length = values[:3]
    if mode not in (0, 1) or not 1 <= key_length <= 16:
        return -1, b""
    max_text_length = 256 if mode == 0 else 512
    if (not 0 <= text_length <= max_text_length
            or len(values) != 3 + text_length + key_length):
        return -1, b""
    text = values[3:3 + text_length]
    key_values = values[3 + text_length:]
    if (any(not 0 <= byte <= 127 for byte in text)
            or any(not 65 <= byte <= 90 for byte in key_values)
            or len(set(key_values)) != key_length):
        return -1, b""
    key = bytes(key_values)
    square = (b"NA1C3H", b"8TB2OM", b"E5WRPD", b"4F67GI", b"9J0KLQ", b"SUVXYZ")
    labels = b"ADFGVX"
    if mode == 0:
        normalized = [byte - 32 if 97 <= byte <= 122 else byte for byte in text]
        alphabet = {square[row][column]: bytes((labels[row], labels[column]))
                    for row in range(6) for column in range(6)}
        fractionated = b"".join(alphabet[byte] for byte in normalized
                                if 65 <= byte <= 90 or 48 <= byte <= 57)
        row_count = (len(fractionated) + key_length - 1) // key_length
        grid = [[None] * key_length for _ in range(row_count)]
        for index, label in enumerate(fractionated):
            grid[index // key_length][index % key_length] = label
        ciphertext = bytes(grid[row][column]
                           for column in sorted(range(key_length), key=key.__getitem__)
                           for row in range(row_count) if grid[row][column] is not None)
        return len(ciphertext), ciphertext
    if text_length % 2 or any(byte not in labels for byte in text):
        return -1, b""
    row_count = (text_length + key_length - 1) // key_length
    grid = [[None] * key_length for _ in range(row_count)]
    offset = 0
    for column in sorted(range(key_length), key=key.__getitem__):
        for row in range(row_count):
            if offset < text_length:
                grid[row][column] = text[offset]
                offset += 1
    fractionated = bytes(cell for row in grid for cell in row if cell is not None)
    decode = {bytes((labels[row], labels[column])): square[row][column]
              for row in range(6) for column in range(6)}
    plaintext = bytes(decode[fractionated[index:index + 2]]
                      for index in range(0, len(fractionated), 2))
    return len(plaintext), plaintext


def upper_verifier_oracle(values: tuple[int, ...] | list[int]) -> tuple[int, bytes]:
    """Uppercase ASCII lowercase bytes while enforcing the package's whitespace domain."""
    if (not isinstance(values, (tuple, list)) or len(values) > 256
            or any(type(value) is not int or not -(2**63) <= value < 2**63 for value in values)):
        return -1, b""
    if any(not 0 <= value <= 127 or value in range(9, 14) or value == 32 for value in values):
        return -1, b""
    output = bytes(value - 32 if 97 <= value <= 122 else value for value in values)
    return len(output), output


def all_construct_verifier_oracle(values: tuple[int, ...] | list[int]) -> tuple[int, bytes]:
    """Enumerate ordered target constructions while preserving duplicate bank entries."""
    if (not isinstance(values, (tuple, list)) or not 2 <= len(values) <= 36
            or any(type(value) is not int or not -(2**63) <= value < 2**63 for value in values)):
        return -1, b""
    target_length = values[0]
    if not 0 <= target_length <= 6 or len(values) < target_length + 2:
        return -1, b""
    target_values = values[1:1 + target_length]
    if any(not 97 <= value <= 122 for value in target_values):
        return -1, b""
    target = bytes(target_values)
    position = 1 + target_length
    word_count = values[position]
    position += 1
    if not 0 <= word_count <= 4:
        return -1, b""
    words: list[bytes] = []
    for _ in range(word_count):
        if position >= len(values) or not 1 <= values[position] <= 6:
            return -1, b""
        word_length = values[position]
        position += 1
        if word_length > len(values) - position:
            return -1, b""
        word_values = values[position:position + word_length]
        if any(not 97 <= value <= 122 for value in word_values):
            return -1, b""
        words.append(bytes(word_values))
        position += word_length
    if position != len(values):
        return -1, b""
    paths: list[list[tuple[bytes, ...]]] = [[] for _ in range(target_length + 1)]
    paths[0] = [()]
    for start in range(target_length + 1):
        for word in words:
            end = start + len(word)
            if end <= target_length and target.startswith(word, start):
                paths[end].extend(prefix + (word,) for prefix in paths[start])
    constructions = paths[target_length]
    output = bytearray()
    for construction in constructions:
        output.append(len(construction))
        for word in construction:
            output.append(len(word))
            output.extend(word)
    return len(constructions), bytes(output)


def allocation_number_verifier_oracle(values: tuple[int, ...] | list[int]) -> tuple[int, bytes]:
    """Partition a bounded byte count into one-based contiguous ranges."""
    if (not isinstance(values, (tuple, list)) or len(values) != 2
            or any(type(value) is not int or not -(2**63) <= value < 2**63 for value in values)):
        return -1, b""
    total, partitions = values
    if not 1 <= total <= 1_000_000 or not 1 <= partitions <= 128 or partitions > total:
        return -1, b""
    block = total // partitions
    ranges = []
    for index in range(partitions):
        start = index * block + 1
        end = (index + 1) * block if index + 1 < partitions else total
        ranges.append(f"{start}-{end}")
    output = ",".join(ranges).encode("ascii")
    return len(output), output


def booths_algorithm_verifier_oracle(values: tuple[int, ...] | list[int]) -> tuple[int, bytes]:
    """Return the smallest cyclic ASCII rotation using a direct definition oracle."""
    if (not isinstance(values, (tuple, list)) or not 1 <= len(values) <= 256
            or any(type(value) is not int or not -(2**63) <= value < 2**63
                   or not 0 <= value <= 127 for value in values)):
        return -1, b""
    text = bytes(values)
    output = min(text[index:] + text[:index] for index in range(len(text)))
    return len(output), output


def association_verifier_oracle(values: tuple[int, ...] | list[int]) -> tuple[int, bytes]:
    """Return every nonempty itemset with support at least one, in canonical order."""
    if (not isinstance(values, (tuple, list)) or len(values) < 2
            or any(type(value) is not int or not -(2**63) <= value < 2**63 for value in values)):
        return -1, b""
    transaction_count, item_count = values[:2]
    transactions = values[2:]
    if (not 1 <= transaction_count <= 64 or not 1 <= item_count <= 11
            or len(transactions) != transaction_count
            or any(not 0 <= mask < (1 << item_count) for mask in transactions)):
        return -1, b""
    records = []
    for itemset_mask in range(1, 1 << item_count):
        support_count = sum((transaction & itemset_mask) == itemset_mask
                            for transaction in transactions)
        if support_count:
            records.append((itemset_mask.bit_count(), itemset_mask, support_count))
    records.sort()
    output = b"".join(struct.pack("<qq", mask, support)
                      for _, mask, support in records)
    return len(output), output


def auto_correlation_verifier_oracle(values: tuple[int, ...] | list[int]) -> tuple[int, bytes]:
    """Compute full linear autocorrelation directly from signed integer lags."""
    if (not isinstance(values, (tuple, list)) or not values
            or any(type(value) is not int or not -(2**63) <= value < 2**63 for value in values)):
        return -1, b""
    count, samples = values[0], values[1:]
    if (not 1 <= count <= 64 or len(samples) != count
            or any(not -1_000_000 <= sample <= 1_000_000 for sample in samples)):
        return -1, b""
    output = []
    for lag in range(-(count - 1), count):
        start = max(0, -lag)
        end = min(count, count - lag)
        output.append(sum(samples[index] * samples[index + lag] for index in range(start, end)))
    return len(output) * 8, b"".join(struct.pack("<q", value) for value in output)


def cross_correlation_verifier_oracle(values: tuple[int, ...] | list[int]) -> tuple[int, bytes]:
    """Accumulate every pair into its reversed-y linear-convolution position."""
    if (not isinstance(values, (tuple, list)) or not 4 <= len(values) <= 66
            or any(type(value) is not int or not -(2**63) <= value < 2**63 for value in values)):
        return -1, b""
    x_count, y_count = values[:2]
    if (not 1 <= x_count <= 32 or not 1 <= y_count <= 32
            or len(values) != 2 + x_count + y_count):
        return -1, b""
    x_values = values[2:2 + x_count]
    y_values = values[2 + x_count:]
    if (any(not -1_000_000 <= value <= 1_000_000 for value in x_values)
            or any(not -1_000_000 <= value <= 1_000_000 for value in y_values)):
        return -1, b""
    coefficients = [0] * (x_count + y_count - 1)
    for x_index, x_value in enumerate(x_values):
        for y_index, y_value in enumerate(y_values):
            coefficients[x_index + y_count - 1 - y_index] += x_value * y_value
    encoded = b"".join(struct.pack("<q", value) for value in coefficients)
    return len(encoded), encoded


def baconian_cipher_verifier_oracle(values: tuple[int, ...] | list[int]) -> tuple[int, bytes]:
    """Independent model of the Java, Python, and Rust Baconian dialects."""
    if (not isinstance(values, (tuple, list)) or not 2 <= len(values) <= 1026
            or any(type(value) is not int or not -(2**63) <= value < 2**63 for value in values)):
        return -1, b""
    mode, dialect, *payload = values
    if mode not in (0, 1) or dialect not in (0, 1, 2) or any(not 0 <= byte <= 127 for byte in payload):
        return -1, b""
    standard = tuple(f"{index:05b}".replace("0", "A").replace("1", "B") for index in range(26))
    python_codes = (
        "AAAAA", "AAAAB", "AAABA", "AAABB", "AABAA", "AABAB", "AABBA", "AABBB",
        "ABAAA", "BBBAA", "ABAAB", "ABABA", "ABABB", "ABBAA", "ABBAB", "ABBBA",
        "ABBBB", "BAAAA", "BAAAB", "BAABA", "BAABB", "BBBAB", "BABAA", "BABAB",
        "BABBA", "BABBB",
    )
    if mode == 0:
        output = bytearray()
        for byte in payload:
            upper = byte - 32 if 97 <= byte <= 122 else byte
            if dialect == 0:
                if 65 <= upper <= 90:
                    output.extend(standard[9 if upper == 73 else upper - 65].encode("ascii"))
            elif dialect == 1:
                if byte == 32:
                    output.append(32)
                elif 65 <= upper <= 90:
                    output.extend(python_codes[upper - 65].encode("ascii"))
                else:
                    return -1, b""
            else:
                if 65 <= upper <= 90:
                    index = upper - 65
                    if index >= 24:
                        return -1, b""
                    output.extend(standard[index].encode("ascii"))
                else:
                    output.append(byte)
        return len(output), bytes(output)
    if dialect == 0:
        if len(payload) % 5 or any(byte not in (65, 66) for byte in payload):
            return -1, b""
        output = bytearray()
        for start in range(0, len(payload), 5):
            code = int(bytes(payload[start:start + 5]).replace(b"A", b"0").replace(b"B", b"1"), 2)
            if code > 25:
                return -1, b""
            output.append(73 if code in (8, 9) else 65 + code)
        return len(output), bytes(output)
    if dialect == 1:
        if any(byte not in (32, 65, 66) for byte in payload):
            return -1, b""
        inverse = {code.encode("ascii"): 97 + index for index, code in enumerate(python_codes)}
        words = bytes(payload).split()
        output_words = []
        for word in words:
            if len(word) % 5:
                return -1, b""
            decoded = bytearray()
            for start in range(0, len(word), 5):
                value = inverse.get(word[start:start + 5])
                if value is None:
                    return -1, b""
                decoded.append(value)
            output_words.append(bytes(decoded))
        output = b" ".join(output_words)
        return len(output), output
    inverse = {code.encode("ascii"): 65 + index for index, code in enumerate(standard[:24])}
    encoded = bytes(payload)
    output = bytes(inverse.get(encoded[start:start + 5], 32) for start in range(0, len(encoded), 5))
    return len(output), output


def a1z26_cipher_verifier_oracle(values: tuple[int, ...] | list[int]) -> tuple[int, bytes]:
    """Map an ASCII letter sequence to its one-byte, one-based alphabet positions."""
    if (not isinstance(values, (tuple, list)) or len(values) > 66
            or any(type(value) is not int or not -(2**63) <= value < 2**63 for value in values)):
        return -1, b""
    output = bytearray()
    for value in values:
        if 65 <= value <= 90:
            output.append(value - 64)
        elif 97 <= value <= 122:
            output.append(value - 96)
        else:
            return -1, b""
    return len(output), bytes(output)


def a1z26_decipher_verifier_oracle(values: tuple[int, ...] | list[int]) -> tuple[int, bytes]:
    """Map one-based alphabet positions to lowercase ASCII letters."""
    if (not isinstance(values, (tuple, list)) or len(values) > 66
            or any(type(value) is not int or not -(2**63) <= value < 2**63 for value in values)
            or any(not 1 <= value <= 26 for value in values)):
        return -1, b""
    output = bytes(96 + value for value in values)
    return len(output), output


def atbash_cipher_verifier_oracle(values: tuple[int, ...] | list[int]) -> tuple[int, bytes]:
    """Apply case-preserving Atbash to 7-bit ASCII, copying other bytes."""
    if (not isinstance(values, (tuple, list)) or len(values) > 66
            or any(type(value) is not int or not -(2**63) <= value < 2**63
                   or not 0 <= value <= 127 for value in values)):
        return -1, b""
    output = bytearray(values)
    for index, value in enumerate(output):
        if 65 <= value <= 90:
            output[index] = 155 - value
        elif 97 <= value <= 122:
            output[index] = 219 - value
    return len(output), bytes(output)


def title_case_oracle(values: tuple[int, ...] | list[int]) -> tuple[int, bytes]:
    """Model the package's ASCII title-case contract from its packed array."""
    if (not isinstance(values, (tuple, list)) or not values
            or any(type(value) is not int or not -(2**63) <= value < 2**63 for value in values)):
        return -1, b""
    byte_length, text_values = values[0], values[1:]
    if not 0 <= byte_length <= 256 or len(text_values) != byte_length:
        return -1, b""
    if byte_length == 0:
        return 0, b"\0"

    output = bytearray()
    at_word_start = True
    for index, value in enumerate(text_values):
        if 65 <= value <= 90 or 97 <= value <= 122:
            if at_word_start:
                output.append(value - 32 if 97 <= value <= 122 else value)
                at_word_start = False
            else:
                output.append(value + 32 if 65 <= value <= 90 else value)
        elif (value == 32 and not at_word_start and index + 1 < byte_length
              and text_values[index + 1] != 32):
            output.append(32)
            at_word_start = True
        else:
            return -1, b""
    if at_word_start:
        return -1, b""
    output.append(0)
    return byte_length, bytes(output)


def weight_conversions_oracle(values: tuple[int, ...] | list[int]) -> tuple[int, bytes]:
    """Model Ruby's six strings using decimal rounding of each float's shortest repr."""
    if (not isinstance(values, (tuple, list)) or len(values) != 2
            or any(type(value) is not int or not -(2**63) <= value < 2**63 for value in values)):
        return -1, b""
    operation, amount = values
    if not 0 <= operation <= 5 or not -1_000_000 <= amount <= 1_000_000:
        return -1, b""

    def ruby_float_text(value: float) -> str:
        rounded = Decimal(str(value)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        text = format(rounded, "f")
        return text[:-1] if text.endswith("0") else text

    if operation == 0:
        text = f"{amount} kg = {amount * 1000} g"
    elif operation == 1:
        text = f"{amount} g = {amount // 1000} kg"
    elif operation == 2:
        text = f"{amount} lb = {amount * 16} oz"
    elif operation == 3:
        text = f"{amount} oz = {amount // 16} lb"
    elif operation == 4:
        text = f"{amount} kg = {ruby_float_text(float(amount) * 2.205)} lb"
    else:
        text = f"{amount} lb = {ruby_float_text(float(amount) / 2.205)} kg"
    encoded = text.encode("ascii") + b"\0"
    return len(encoded) - 1, encoded


def red_black_tree_oracle(values: tuple[int, ...] | list[int]) -> tuple[int, bytes]:
    """Model unique-key tree traces with a set and sorted final keys."""
    if (not isinstance(values, (tuple, list)) or not values
            or any(type(value) is not int or not -(2**63) <= value < 2**63 for value in values)):
        return -1, b""
    operation_count = values[0]
    if not 0 <= operation_count <= 128 or len(values) != 1 + 2 * operation_count:
        return -1, b""
    keys: set[int] = set()
    searches: list[int] = []
    for offset in range(1, len(values), 2):
        operation, key = values[offset:offset + 2]
        if operation not in (0, 1, 2) or not -(2**31) <= key <= 2**31 - 1:
            return -1, b""
        if operation == 0:
            if key in keys:
                return -1, b""
            keys.add(key)
        elif operation == 1:
            searches.append(int(key in keys))
        else:
            if key not in keys:
                return -1, b""
            keys.remove(key)
    ordered = sorted(keys)
    output_values = [len(ordered), *ordered, len(searches), *searches]
    output = b"".join(struct.pack("<q", value) for value in output_values)
    return len(output), output


def lru_verifier_oracle(
    values: tuple[int, ...] | list[int] | None,
    output_capacity: int | None = None,
    output_is_null: bool = False,
    input_is_null: bool = False,
    input_length: int | None = None,
) -> tuple[int, bytes]:
    """Independent LRU reference using OrderedDict recency operations."""
    if type(output_is_null) is not bool or type(input_is_null) is not bool:
        return LRU_INVALID_RESULT, b""
    if output_capacity is not None and (
        type(output_capacity) is not int or output_capacity < 0
    ):
        return LRU_INVALID_RESULT, b""
    if input_length is not None and (
        type(input_length) is not int or input_length < 0
    ):
        return LRU_INVALID_RESULT, b""
    if input_is_null or not isinstance(values, (list, tuple)):
        return LRU_INVALID_RESULT, b""
    if input_length is not None and input_length != len(values):
        return LRU_INVALID_RESULT, b""
    if not 2 <= len(values) <= LRU_MAX_INPUT_LENGTH:
        return LRU_INVALID_RESULT, b""
    if any(type(value) is not int or not LRU_I64_MIN <= value <= LRU_I64_MAX
           for value in values):
        return LRU_INVALID_RESULT, b""

    capacity, operation_count = values[:2]
    if (not LRU_MIN_CAPACITY <= capacity <= LRU_MAX_CAPACITY
            or not 0 <= operation_count <= LRU_MAX_OPERATION_COUNT
            or len(values) != 2 + 3 * operation_count):
        return LRU_INVALID_RESULT, b""

    cache: OrderedDict[int, int] = OrderedDict()
    inserted_keys: set[int] = set()
    records: list[int] = []
    for offset in range(2, len(values), 3):
        opcode, key, value = values[offset:offset + 3]
        if not LRU_MIN_KEY <= key <= LRU_MAX_KEY:
            return LRU_INVALID_RESULT, b""
        if opcode == 0:
            if not LRU_MIN_VALUE <= value <= LRU_MAX_VALUE or key in inserted_keys:
                return LRU_INVALID_RESULT, b""
            inserted_keys.add(key)
            if len(cache) == capacity:
                cache.popitem(last=False)
            cache[key] = value
            records.extend((0, 0))
        elif opcode == 1:
            if value != 0 or key not in cache:
                return LRU_INVALID_RESULT, b""
            records.extend((1, 1, cache[key]))
            cache.move_to_end(key)
        else:
            return LRU_INVALID_RESULT, b""

    records.extend((2, len(cache)))
    for key, value in cache.items():
        records.extend((key, value))
    output = b"".join(struct.pack("<q", value) for value in records)
    if len(output) > LRU_MAX_OUTPUT_BYTES:
        return LRU_INVALID_RESULT, b""
    if output_is_null or (output_capacity is not None and output_capacity < len(output)):
        return LRU_OUTPUT_ERROR, b""
    return len(output), output


def polybench_adi_verifier_oracle(
        values: tuple[int, ...] | list[int], capacity: int | None = None,
        output_is_null: bool = False, input_is_null: bool = False,
        input_length: int | None = None) -> tuple[int, bytes]:
    """Independent 2D-array model for the bounded PolyBench ADI kernel."""
    if (capacity is not None and (type(capacity) is not int or capacity < 0)):
        return -1, b""
    if (type(output_is_null) is not bool or type(input_is_null) is not bool
            or input_is_null or not isinstance(values, (tuple, list))
            or input_length is not None
            and (type(input_length) is not int or input_length != len(values))
            or len(values) != 2
            or any(type(value) is not int or not -(1 << 63) <= value < (1 << 63)
                   for value in values)):
        return -1, b""
    n, tsteps = values
    if not 1 <= n <= 32 or not 1 <= tsteps <= 20:
        return -1, b""

    u = [[float(i + n - j) / float(n) for j in range(n)] for i in range(n)]
    v = [[0.0 for _ in range(n)] for _ in range(n)]
    p = [[0.0 for _ in range(n)] for _ in range(n)]
    q = [[0.0 for _ in range(n)] for _ in range(n)]
    dx = 1.0 / float(n)
    dy = 1.0 / float(n)
    dt = 1.0 / float(tsteps)
    mul1 = 2.0 * dt / (dx * dx)
    mul2 = 1.0 * dt / (dy * dy)
    a = -mul1 / 2.0
    b = 1.0 + mul1
    c = a
    d = -mul2 / 2.0
    e = 1.0 + mul2
    f = d

    for _ in range(tsteps):
        for i in range(1, n - 1):
            v[0][i] = 1.0
            p[i][0] = 0.0
            q[i][0] = v[0][i]
            for j in range(1, n - 1):
                denominator = a * p[i][j - 1] + b
                p[i][j] = -c / denominator
                q[i][j] = (
                    -d * u[j][i - 1]
                    + (1.0 + 2.0 * d) * u[j][i]
                    - f * u[j][i + 1]
                    - a * q[i][j - 1]
                ) / denominator
            v[n - 1][i] = 1.0
            for j in range(n - 2, 0, -1):
                v[j][i] = p[i][j] * v[j + 1][i] + q[i][j]

        for i in range(1, n - 1):
            u[i][0] = 1.0
            p[i][0] = 0.0
            q[i][0] = u[i][0]
            for j in range(1, n - 1):
                denominator = d * p[i][j - 1] + e
                p[i][j] = -f / denominator
                q[i][j] = (
                    -a * v[i - 1][j]
                    + (1.0 + 2.0 * a) * v[i][j]
                    - c * v[i + 1][j]
                    - d * q[i][j - 1]
                ) / denominator
            u[i][n - 1] = 1.0
            for j in range(n - 2, 0, -1):
                u[i][j] = p[i][j] * u[i][j + 1] + q[i][j]

    output = struct.pack("<" + "d" * (n * n), *(value for row in u for value in row))
    if output_is_null or (capacity is not None and capacity < len(output)):
        return -2, b""
    return len(output), output


BENTLEY_OTTMANN_MAX_SEGMENTS = 24
BENTLEY_OTTMANN_MAX_COORDINATE = 1000
BENTLEY_OTTMANN_MAX_INPUT_LENGTH = 1 + 4 * BENTLEY_OTTMANN_MAX_SEGMENTS
BENTLEY_OTTMANN_MAX_INTERSECTIONS = (
    BENTLEY_OTTMANN_MAX_SEGMENTS * (BENTLEY_OTTMANN_MAX_SEGMENTS - 1) // 2
)
BENTLEY_OTTMANN_MAX_OUTPUT_BYTES = 8 * (1 + 2 * BENTLEY_OTTMANN_MAX_INTERSECTIONS)


def bentley_ottmann_verifier_oracle(
        values: tuple[int, ...] | list[int], capacity: int | None = None,
        output_is_null: bool = False, input_is_null: bool = False,
        input_length: int | None = None) -> tuple[int, bytes]:
    """Independent pairwise exact-geometry oracle for the sweep-line ports."""
    if (not isinstance(values, (tuple, list))
            or len(values) > BENTLEY_OTTMANN_MAX_INPUT_LENGTH
            or any(type(value) is not int or not -(1 << 63) <= value < (1 << 63)
                   for value in values)
            or (capacity is not None
                and (type(capacity) is not int
                     or not 0 <= capacity <= MAX_OUTPUT_CAPACITY))
            or type(output_is_null) is not bool or type(input_is_null) is not bool):
        return -1, b""
    effective_length = len(values) if input_length is None else input_length
    if (type(effective_length) is not int
            or not 0 <= effective_length <= BENTLEY_OTTMANN_MAX_INPUT_LENGTH):
        return -1, b""
    if input_is_null:
        return -1, b""
    if effective_length != len(values) or not values:
        return -1, b""

    segment_count = values[0]
    if (not 0 <= segment_count <= BENTLEY_OTTMANN_MAX_SEGMENTS
            or len(values) != 1 + 4 * segment_count):
        return -1, b""

    segments: list[tuple[int, int, int, int]] = []
    endpoint_x: set[int] = set()
    for offset in range(1, len(values), 4):
        x1, y1, x2, y2 = values[offset:offset + 4]
        if (any(not -BENTLEY_OTTMANN_MAX_COORDINATE <= coordinate
                    <= BENTLEY_OTTMANN_MAX_COORDINATE
                for coordinate in (x1, y1, x2, y2)) or x1 == x2):
            return -1, b""
        if x1 > x2:
            x1, y1, x2, y2 = x2, y2, x1, y1
        segments.append((x1, y1, x2, y2))
        endpoint_x.update((x1, x2))
    if len(endpoint_x) != 2 * segment_count:
        return -1, b""

    intersections: set[tuple[int, int]] = set()
    intersection_x: set[int] = set()
    for index, (x1, y1, x2, y2) in enumerate(segments):
        rx, ry = x2 - x1, y2 - y1
        for qx1, qy1, qx2, qy2 in segments[index + 1:]:
            sx, sy = qx2 - qx1, qy2 - qy1
            qpx, qpy = qx1 - x1, qy1 - y1
            denominator = rx * sy - ry * sx
            if denominator == 0:
                if qpx * ry - qpy * rx == 0:
                    if max(x1, qx1) <= min(x2, qx2):
                        return -1, b""
                continue
            t_numerator = qpx * sy - qpy * sx
            u_numerator = qpx * ry - qpy * rx
            if denominator < 0:
                denominator = -denominator
                t_numerator = -t_numerator
                u_numerator = -u_numerator
            if not (0 <= t_numerator <= denominator
                    and 0 <= u_numerator <= denominator):
                continue
            if (t_numerator in (0, denominator)
                    or u_numerator in (0, denominator)):
                return -1, b""
            x_numerator = x1 * denominator + t_numerator * rx
            y_numerator = y1 * denominator + t_numerator * ry
            if x_numerator % denominator or y_numerator % denominator:
                return -1, b""
            point = (x_numerator // denominator, y_numerator // denominator)
            if point[0] in endpoint_x or point[0] in intersection_x:
                return -1, b""
            intersections.add(point)
            intersection_x.add(point[0])

    ordered = sorted(intersections)
    output_values = [len(ordered)]
    for x, y in ordered:
        output_values.extend((x, y))
    output = b"".join(struct.pack("<q", value) for value in output_values)
    if (len(output) > BENTLEY_OTTMANN_MAX_OUTPUT_BYTES
            or output_is_null or (capacity is not None and capacity < len(output))):
        return -2, b""
    return len(output), output


def validate_bentley_ottmann_workload(workload: dict) -> None:
    """Check the package metadata, pinned source, and fixture results."""
    pinned_commit = "e43ec3897e48f23843972d02cd05a5bb1b6864a2"
    if (set(workload) != {"schema_version", "id", "algorithm", "function_symbol",
                          "input", "output", "measurement", "cases"}
            or workload.get("schema_version") != 1
            or workload.get("id") != "bentley-ottmann-general-position-i64-array-bytes-v1"
            or workload.get("algorithm") != "bentley_ottmann"
            or workload.get("function_symbol") != "bentley_ottmann"
            or workload.get("input") != {
                "kind": "signed_i64_array",
                "layout": ["segment_count", "x1", "y1", "x2", "y2", "..."],
                "segment_count_range": [0, BENTLEY_OTTMANN_MAX_SEGMENTS],
                "coordinate_range": [-BENTLEY_OTTMANN_MAX_COORDINATE,
                                     BENTLEY_OTTMANN_MAX_COORDINATE],
                "preconditions": [
                    "nonvertical segments", "no shared endpoints", "no collinear overlaps",
                    "proper intersections only at integer lattice points",
                    "all endpoint and intersection x-coordinates are distinct",
                ],
                "invalid_result": -1,
                "insufficient_output_capacity_result": -2,
            }
            or workload.get("output") != {
                "kind": "little_endian_signed_i64_vector",
                "layout": ["intersection_count", "x0", "y0", "x1", "y1", "..."],
                "points_order": "lexicographic x then y",
                "return_value": "number of output bytes",
            }
            or workload.get("measurement") != {
                "comparison_model": "i64_array_bytes_output_call",
                "sample_count": 5,
                "warmup_rounds": 1,
                "repetitions_per_sample": 100,
            }):
        raise ValueError("bentley_ottmann metadata differs from its bounded sweep-line contract")

    readme = (ROOT / "benchmarks" / "b" / "bentley_ottmann" / "README.md").read_text(
        encoding="utf-8")
    if (pinned_commit not in readme
            or "TheAlgorithms/Java" not in readme
            or "proper crossing at an integer lattice point" not in readme
            or "source-inspired" not in readme):
        raise ValueError("bentley_ottmann README lost its pinned source or contract explanation")

    cases = workload.get("cases")
    expected_ids = {"single_integer_crossing", "no_intersection"}
    if (not isinstance(cases, list)
            or any(not isinstance(case, dict) for case in cases)
            or {case.get("id") for case in cases if isinstance(case, dict)} != expected_ids
            or len(cases) != len(expected_ids)):
        raise ValueError("bentley_ottmann workload fixtures differ from the reviewed corpus")
    for case in cases:
        if (not isinstance(case.get("input_values"), list)
                or type(case.get("expected_result")) is not int
                or not isinstance(case.get("expected_output_hex"), str)):
            raise ValueError(f"malformed bentley_ottmann workload fixture: {case.get('id')}")
        capacity = case.get("output_capacity")
        result, output = bentley_ottmann_verifier_oracle(
            case["input_values"], capacity=capacity,
            output_is_null=case.get("output_is_null", False),
            input_is_null=case.get("input_is_null", False),
            input_length=case.get("input_length"))
        if (result != case["expected_result"]
                or output.hex() != case["expected_output_hex"].lower()):
            raise ValueError(f"bentley_ottmann fixture disagrees with independent oracle: {case['id']}")


def bentley_ottmann_corpus(workload: dict) -> tuple[str, int]:
    validate_bentley_ottmann_workload(workload)
    records_by_key: dict[tuple[tuple[int, ...], int, bool, bool, int], tuple[int, bytes]] = {}

    def add(values: tuple[int, ...], capacity: int = BENTLEY_OTTMANN_MAX_OUTPUT_BYTES,
            *, output_is_null: bool = False, input_is_null: bool = False,
            input_length: int | None = None) -> None:
        values = tuple(values)
        effective_length = len(values) if input_length is None else input_length
        if (len(values) > BENTLEY_OTTMANN_MAX_INPUT_LENGTH
                or type(capacity) is not int or not 0 <= capacity <= MAX_OUTPUT_CAPACITY
                or type(output_is_null) is not bool or type(input_is_null) is not bool
                or type(effective_length) is not int
                or not 0 <= effective_length <= BENTLEY_OTTMANN_MAX_INPUT_LENGTH):
            raise ValueError("bentley_ottmann generated input/output framing is out of range")
        result, output = bentley_ottmann_verifier_oracle(
            values, capacity, output_is_null, input_is_null, effective_length)
        if result >= 0:
            if result != len(output) or result > BENTLEY_OTTMANN_MAX_OUTPUT_BYTES:
                raise ValueError("bentley_ottmann success violates its output bound")
        elif output:
            raise ValueError("bentley_ottmann errors must not write output")
        key = (values, capacity, output_is_null, input_is_null, effective_length)
        value = (result, output)
        if key in records_by_key and records_by_key[key] != value:
            raise ValueError("bentley_ottmann corpus key collides with a distinct output call")
        records_by_key[key] = value

    for case in workload["cases"]:
        values = tuple(case["input_values"])
        _unbounded_result, unbounded_output = bentley_ottmann_verifier_oracle(values)
        capacity = case.get("output_capacity", len(unbounded_output))
        add(values, capacity, output_is_null=case.get("output_is_null", False),
            input_is_null=case.get("input_is_null", False),
            input_length=case.get("input_length", len(values)))

    crossing = tuple(next(case["input_values"] for case in workload["cases"]
                         if case["id"] == "single_integer_crossing"))
    three_crossings = (3, 0, 0, 12, 0, 1, -3, 10, 6, 2, 4, 11, -5)
    coordinate_edges = (2, -1000, -1000, -999, -1000, 999, 1000, 1000, 1000)
    maximum_count = [BENTLEY_OTTMANN_MAX_SEGMENTS]
    for index in range(BENTLEY_OTTMANN_MAX_SEGMENTS):
        maximum_count.extend((-1000 + 2 * index, -900 + 60 * index,
                              -999 + 2 * index, -900 + 60 * index))
    for values in (crossing, three_crossings, coordinate_edges, tuple(maximum_count)):
        add(values)

    crossing_result, crossing_output = bentley_ottmann_verifier_oracle(crossing)
    if crossing_result != 24 or len(crossing_output) != 24:
        raise ValueError("bentley_ottmann capacity probe no longer has its expected fixed size")
    for capacity in (0, 7, 8, 9):
        add((0,), capacity)
    for capacity in (0, crossing_result - 1, crossing_result, crossing_result + 1):
        add(crossing, capacity)
    add(crossing, output_is_null=True)
    add(three_crossings, output_is_null=True)

    malformed = (
        (), (-1,), (BENTLEY_OTTMANN_MAX_SEGMENTS + 1,), (1,),
        (1, -1001, 0, -999, 0), (1, 5, 0, 5, 1),
    )
    for values in malformed:
        add(tuple(values))
    add((0,), input_length=2)
    add((-1,), 0, output_is_null=True)
    add((), input_is_null=True, input_length=1)

    records = [(*key, result, output) for key, (result, output) in records_by_key.items()]
    records.sort(key=lambda record: record[:5])
    lines = [f"{len(records)}\n"]
    for values, capacity, output_is_null, input_is_null, input_length, result, output in records:
        encoded = output.hex() if output else "-"
        header = f"{input_length} {result} {len(output)} {capacity} {int(input_is_null)} {int(output_is_null)}"
        checker_values = (0,) * input_length if input_is_null else values
        values_text = "" if not checker_values else " " + " ".join(map(str, checker_values))
        lines.append(f"{header}{values_text} {encoded}\n")
    return "".join(lines), len(records)


