        def add(values: tuple[int, ...], capacity: int = default_capacity,
                output_is_null: bool = False, input_is_null: bool = False,
                input_length: int | None = None) -> None:
            values = tuple(values)
            if input_length is None:
                input_length = len(values)
            if (len(values) > MAX_GENERATE_SUB_SETS_PARSEABLE_INPUT_LENGTH
                    or any(type(value) is not int or not -(1 << 63) <= value < (1 << 63)
                           for value in values)
                    or type(capacity) is not int
                    or not 0 <= capacity <= GENERATE_SUB_SETS_MAX_OUTPUT_BYTES
                    or type(output_is_null) is not bool or type(input_is_null) is not bool
                    or type(input_length) is not int
                    or (input_is_null and (values or not 1 <= input_length <= MAX_GENERATE_SUB_SETS_PARSEABLE_INPUT_LENGTH
                                           or output_is_null))
                    or (not input_is_null and input_length != len(values))):
                raise ValueError("generate_sub_sets generated input/output framing is out of range")
            result, output = generate_sub_sets_oracle(
                values, capacity, output_is_null, input_is_null, input_length)
            if (result >= 0 and result != len(output)
                    or result < 0 and (result not in (GENERATE_SUB_SETS_INVALID_RESULT,
                                                      GENERATE_SUB_SETS_OUTPUT_ERROR) or output)):
                raise ValueError("generate_sub_sets oracle returned inconsistent byte framing")
            key = (values, capacity, output_is_null, input_is_null, input_length)
            value = (result, output)
            if key in cases and cases[key] != value:
                raise ValueError("generate_sub_sets probe collides with a distinct output call")
            cases[key] = value

        for case in workload["cases"]:
            values = tuple(case["input_values"])
            capacity = case.get("workspace_bytes", default_capacity)
            output_is_null = case.get("output_is_null", False)
